// Writes parser/meta_grammar_source.mbt: PEG.js' grammar (src/parser.pegjs)
// as a MoonBit string, used by the self-hosting test.
//
//   node tools/gen-meta-source.js > parser/meta_grammar_source.mbt
"use strict";
const fs = require("fs");
const path = require("path");
const { mbtString } = require("./gen-program");

const src = fs.readFileSync(path.join(__dirname, "..", ".repos", "pegjs", "src", "parser.pegjs"), "utf8");
process.stdout.write(
  "// Code generated by tools/gen-meta-source.js from src/parser.pegjs. DO NOT EDIT.\n\n" +
  "///|\n/// The PEG.js grammar of PEG.js grammars (`src/parser.pegjs`).\n" +
  "pub let meta_grammar_source : String = " + mbtString(src) + "\n");
